const body = $input.first().json.body || {};

// Validate required fields
const message = body.message || body.query;
const context = body.context || {};
const pluginContext = body.plugin_context || {};
const apiKey = pluginContext.api_keys?.anthropic;

// RFC-016: history and attached_file
const history = body.history || [];
const attachedFile = body.attached_file || null;

// NEW: Accept tools array
const tools = body.tools || [];

const errors = [];
if (!message || message.trim() === '') errors.push('message requis');
if (!context.type) errors.push('context.type requis');
if (!apiKey) errors.push('plugin_context.api_keys.anthropic requis');

// Validate history format
if (history.length > 0) {
  const validHistory = history.every(h => h.role && h.content);
  if (!validHistory) errors.push('history[] doit contenir {role, content}');
}

// Validate tools format if provided
if (tools.length > 0) {
  const validTools = tools.every(t => t.id && t.description);
  if (!validTools) errors.push('tools[] doit contenir {id, description}');
}

const truncatedHistory = history.slice(-10);

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  };
}

const minScore = context.min_score || 0.7;
const autoFallback = context.auto_fallback === true;
const allowedActions = context.allowed_actions || context.allowed_intents || ['search', 'info', 'help'];
const llmModel = pluginContext.llm_model || 'claude-3-haiku-20240307';

return {
  json: {
    valid: true,
    message: message.trim(),
    query: message.trim(),
    context: {
      type: context.type,
      allowed_actions: allowedActions,
      min_score: minScore,
      auto_fallback: autoFallback
    },
    history: truncatedHistory,
    attached_file: attachedFile,
    tools: tools,
    plugin_context: pluginContext,
    llm_model: llmModel,
    api_key: apiKey,
    user: body.user || {}
  }
};

const input = $input.first().json;
const prevData = $('Build LLM Payload').first().json;
const statusCode = input.statusCode || 200;

// Handle LLM API error
if (statusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: input.body?.error?.message || 'LLM API error',
        status: 'LLM_ERROR'
      }
    }
  };
}

// Extract LLM response
const content = input.body?.content?.[0]?.text || '';

// Parse JSON from LLM response
let analysis;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  // Default analysis if parsing fails
  analysis = {
    response_type: 'message',
    message: content || 'Je n\'ai pas compris votre demande.',
    intent: { type: 'unknown', confidence: 0.5 },
    query_analysis: {
      original: prevData.message,
      reformulation: prevData.message,
      extracted_terms: '',
      detected_language: 'fr',
      spelling_corrected: false
    },
    proposed_actions: [],
    is_relevant: true,
    rejection_reason: null
  };
}

// Ensure RFC-016 format
const result = {
  success: true,
  response_type: analysis.response_type || 'message',
  message: analysis.message || '',
  intent: analysis.intent || { type: 'unknown', confidence: 0 },
  query_analysis: analysis.query_analysis || {
    original: prevData.message,
    reformulation: prevData.message,
    extracted_terms: '',
    detected_language: 'fr',
    spelling_corrected: false
  },
  proposed_actions: analysis.proposed_actions || [],
  is_relevant: analysis.is_relevant !== false,
  rejection_reason: analysis.rejection_reason || null,
  // Pass through for next nodes
  context: prevData.context,
  plugin_context: prevData.plugin_context,
  user: prevData.user,
  message_original: prevData.message
};

return { json: result };

const input = $input.first().json;

return {
  json: {
    success: true,
    response_type: 'message',
    message: input.rejection_reason || `Cette requête ne concerne pas le contexte ${input.context?.type ||
'demandé'}.`,
    intent: {
      type: 'out_of_context',
      confidence: input.intent?.confidence || 0
    },
    query_analysis: input.query_analysis || {
      original: input.message_original,
      reformulation: input.message_original,
      extracted_terms: '',
      detected_language: 'fr',
      spelling_corrected: false
    },
    proposed_actions: [],
    is_relevant: false,
    rejection_reason: input.rejection_reason
  }
};

// Use LLM's filtered proposed_actions enriched with provided tools metadata
const input = $input.first().json;
const providedTools = $('Validate Input').first().json.tools;
const llmProposedActions = input.proposed_actions || [];

// Create a map of provided tools for quick lookup
const toolsMap = {};
for (const tool of providedTools) {
  toolsMap[tool.id] = tool;
}

// Enrich LLM's proposed_actions with full tool details
const proposedActions = llmProposedActions.map(action => {
  const fullTool = toolsMap[action.id] || {};
  return {
    id: action.id,
    label: action.label || fullTool.label || action.id,
    description: action.description || fullTool.description,
    webhook: fullTool.webhook || null,
    params: action.params || {},
    requires_confirmation: action.requires_confirmation || false,
    estimate: fullTool.estimate || null
  };
});

console.log(`[LLM-Intention] LLM selected ${proposedActions.length}/${providedTools.length} tools`);

return {
  json: {
    success: true,
    response_type: input.response_type || 'action_proposal',
    message: input.message || `${proposedActions.length} action(s) pertinente(s) sur ${providedTools.length}.`,
    intent: input.intent,
    query_analysis: input.query_analysis,
    proposed_actions: proposedActions,
    is_relevant: true,
    rejection_reason: null,
    _tools_source: 'provided_filtered'
  }
};

const qdrantResponse = $input.first().json;
const prevData = $('Parse LLM Response').first().json;

// Webhooks: utilise ceux du context si fournis, sinon defaults
const webhooks = prevData.context?.webhooks || {
  search: '/webhook/llm-web-search',
  scrape: '/webhook/web-scraper',
  local_search: '/webhook/qdrant-search'
};

// NOUVEAU: Si pas relevant, ne pas proposer d'actions
if (!prevData.is_relevant) {
  return {
    json: {
      success: true,
      response_type: 'message',
      message: prevData.message || 'Requête hors contexte.',
      intent: prevData.intent,
      query_analysis: prevData.query_analysis,
      proposed_actions: [],
      is_relevant: false,
      rejection_reason: prevData.rejection_reason
    }
  };
}

// Extract Qdrant results
const qdrantBody = qdrantResponse.body || qdrantResponse;
const qdrantSuccess = qdrantBody.success !== false;
const qdrantResults = qdrantBody.data?.results || [];

// Find best score
let bestScore = 0;
if (qdrantResults.length > 0) {
  bestScore = Math.max(...qdrantResults.map(r => r.score || 0));
}

// Check against threshold
const minScore = prevData.context?.min_score || 0.7;
const aboveThreshold = bestScore >= minScore;

// Start with LLM analysis
let responseType = prevData.response_type || 'message';
let message = prevData.message || '';

// Nettoyer les proposed_actions du LLM (supprimer les webhooks inventés)
let proposedActions = (prevData.proposed_actions || []).map(action => ({
  ...action,
  webhook: null  // On ne fait pas confiance aux webhooks du LLM
}));

// Enrich proposed_actions based on Qdrant results
if (qdrantResults.length > 0 && aboveThreshold) {
  // Good results found - add them to context
  responseType = 'action_proposal';
  message = message || `J'ai trouvé ${qdrantResults.length} résultat(s) pertinent(s).`;

  // Add search results action if not already present
  const hasSearchAction = proposedActions.some(a => a.id === 'return_results');
  if (!hasSearchAction) {
    proposedActions.unshift({
      id: 'return_results',
      label: 'Voir les résultats',
      description: `${qdrantResults.length} résultat(s) trouvé(s) (score: ${Math.round(bestScore * 100)}%)`,
      webhook: null,
      params: { results: qdrantResults },
      requires_confirmation: false,
      estimate: null
    });
  }
} else if (qdrantResults.length === 0 || !aboveThreshold) {
  // No good results - propose web search if relevant
  const hasWebSearch = proposedActions.some(a => a.id === 'web_search' || a.id === 'search');
  if (!hasWebSearch && prevData.is_relevant) {
    const autoFallback = prevData.context?.auto_fallback === true;
    responseType = 'action_proposal';
    const reason = qdrantResults.length === 0
      ? 'Aucun résultat trouvé dans la base locale.'
      : `Résultats peu pertinents (score: ${Math.round(bestScore * 100)}%).`;

    if (autoFallback) {
      message = message || `${reason} Recherche web en cours...`;
    } else {
      message = message || `${reason} Voulez-vous chercher sur le web ?`;
    }

    proposedActions.push({
      id: 'search',
      label: 'Rechercher sur le web',
      description: 'Lancer une recherche web pour trouver des résultats',
      webhook: webhooks.search,  // ← Utilise le webhook du context ou le default
      params: {
        query: Array.isArray(prevData.query_analysis?.extracted_terms)
          ? prevData.query_analysis.extracted_terms.join(' ')
          : (prevData.query_analysis?.extracted_terms || prevData.message_original)
      },
      requires_confirmation: !autoFallback,
      estimate: { credits: 1, unit: 'search', quantity: 1 }
    });
  }
}

return {
  json: {
    success: true,
    response_type: responseType,
    message: message,
    intent: prevData.intent,
    query_analysis: prevData.query_analysis,
    proposed_actions: proposedActions,
    is_relevant: prevData.is_relevant,
    rejection_reason: null,
    _qdrant: {
      searched: true,
      result_count: qdrantResults.length,
      best_score: bestScore,
      above_threshold: aboveThreshold
    }
  }
};

parameters.content:
## MCP - LLM Intention (RFC-016)

 **Endpoint:** POST /webhook/llm-intention

 ### Input
 ```json
 {
   "message": "requ\u00eate utilisateur",
   "context": {
     "type": "recipe|torah|general",
     "allowed_actions": ["search", "web_search", "extract"],
     "min_score": 0.7
   },
   "tools": [
     { "id": "search", "description": "Recherche web" },
     { "id": "translate", "description": "Traduire un texte" }
   ],
   "history": [...],
   "plugin_context": {
     "api_keys": { "anthropic": "sk-ant-..." }
   }
 }
 ```

 **tools** (optionnel): Liste des actions disponibles.
 Si non fourni, utilise les tools par d\u00e9faut.

 ### Output
 ```json
 {
   "success": true,
   "response_type": "message|action_proposal",
   "proposed_actions": [{ "id": "...", ... }]
 }
 ```

